<?php require_once __DIR__.'/../includes/layout.php';require_login(['admin']);
$w=['1=1'];$p=[];foreach(['u'=>'u.email LIKE ?','a'=>'l.action LIKE ?','ip'=>'l.ip LIKE ?'] as $k=>$c)if(($v=trim($_GET[$k]??''))!==''){$w[]=$c;$p[]="%$v%";}
foreach(['from'=>'DATE(l.created_at)>=?','to'=>'DATE(l.created_at)<=?'] as $k=>$c)if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET[$k]??'')){$w[]=$c;$p[]=$_GET[$k];}
$W=implode(' AND ',$w);$page=max(1,(int)($_GET['p']??1));$per=20;$c=$pdo->prepare("SELECT COUNT(*) FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id WHERE $W");$c->execute($p);$pg=paginate((int)$c->fetchColumn(),$per,$page);
$s=$pdo->prepare("SELECT l.*,u.email FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id WHERE $W ORDER BY l.id DESC LIMIT $per OFFSET {$pg['offset']}");$s->execute($p);$rows=$s->fetchAll();page_start('سجل العمليات');ph('سجل التدقيق','سجل الأنشطة والعمليات الأمنية في النظام');?>
<form class="card filters" method="get"><label>المستخدم<input name="u" placeholder="البريد" value="<?=e($_GET['u']??'')?>"></label><label>العملية<input name="a" placeholder="مثال: login" value="<?=e($_GET['a']??'')?>" dir="ltr" style="text-align:right"></label><label>IP<input name="ip" value="<?=e($_GET['ip']??'')?>" dir="ltr" style="text-align:right"></label><label>من<input type="date" name="from" value="<?=e($_GET['from']??'')?>"></label><label>إلى<input type="date" name="to" value="<?=e($_GET['to']??'')?>"></label><button class="btn"><?=ic('filter')?>تصفية</button></form>
<div class="card tbl"><table><tr><th>المستخدم</th><th>العملية</th><th>التفاصيل</th><th>التاريخ والوقت</th><th>IP</th></tr><?php foreach($rows as $r):?><tr><td class="cmain"><?=e($r['email']??'النظام')?></td><td><span class="badge <?=audit_tone((string)$r['action'])?>" title="<?=e($r['action'])?>"><?=e(audit_label((string)$r['action']))?></span></td><td class="wrap"><?=e($r['details'])?></td><td><?=e($r['created_at'])?></td><td dir="ltr" style="text-align:right"><?=e($r['ip'])?></td></tr><?php endforeach;if(!$rows)echo empty_row(5,'لا توجد سجلات','لا توجد عمليات مطابقة للفلاتر.','shield');?></table></div><?php pager($pg['pages'],$page);page_end();
